using FluNET.Context;using FluNET.Compilation;namespace FluNET.Tests.Compilation;[TestFixture]public sealed class GenericHttpResourceTests{[TestCase("https://example.test/a.txt","surface.get.http.text")][TestCase("https://example.test/a.csv","surface.get.http.csv")][TestCase("https://example.test/a.xml","surface.get.http.xml")][TestCase("https://example.test/a.bin","surface.get.http.binary")][TestCase("https://example.test/a.png","surface.get.http.image")]public void HttpExtensionSelectsTypedFrame(string uri,string frame){using FluNETContext context=SurfaceCompilationExtensions.CreateSurfaceContext();SurfaceCompilationResult result=context.CompileSurface($"GET {uri} AS value");Assert.That(result.IsValid,Is.True,string.Join(" | ",result.Lowering.Diagnostics.Select(d=>d.Message)));Assert.That(result.BoundProgram!.Commands.Single().Frame.Id.Value,Is.EqualTo(frame));}}
